53	function getJobIconProps(title: string | null, index: number) {
54	  const lower = (title ?? "").toLowerCase();
55	  let iconIndex = index % JOB_ICONS.length;
56	
57	  if (lower.includes("engineer") || lower.includes("developer") || lower.includes("dev") || lower.includes("code")) {
58	    iconIndex = 1;
59	  } else if (lower.includes("design") || lower.includes("ui") || lower.includes("ux")) {
60	    iconIndex = 2;
61	  } else if (lower.includes("manager") || lower.includes("hr") || lower.includes("talent") || lower.includes("recrui")) {
62	    iconIndex = 3;
63	  } else if (lower.includes("analyt") || lower.includes("data") || lower.includes("scientist")) {
64	    iconIndex = 4;
65	  } else if (lower.includes("market") || lower.includes("growth") || lower.includes("content")) {
66	    iconIndex = 6;
67	  } else if (lower.includes("research") || lower.includes("science") || lower.includes("lab")) {
68	    iconIndex = 7;
69	  }
70	
71	  return {
72	    Icon: JOB_ICONS[iconIndex],
73	    colorClass: ICON_BG_COLORS[iconIndex],
74	  };
75	}
