77	function extractEmploymentTags(jdAnalysis: any): string[] {
78	  if (!jdAnalysis) return [];
79	  const tags: string[] = [];
80	
81	  const empType =
82	    jdAnalysis.employment_type ??
83	    jdAnalysis.job_type ??
84	    jdAnalysis.type ??
85	    jdAnalysis.contract_type ??
86	    null;
87	
88	  const workType =
89	    jdAnalysis.work_type ??
90	    jdAnalysis.location_type ??
91	    jdAnalysis.remote ??
92	    jdAnalysis.work_arrangement ??
93	    null;
94	
95	  if (empType && typeof empType === "string") tags.push(empType);
96	  if (workType && typeof workType === "string") tags.push(workType);
97	
98	  return tags.filter(Boolean).map((t) => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase());
