107	// ─── Circular Score Ring ─────────────────────────────────────────────────────
108	
109	interface CircularScoreProps {
110	  score: number | null;
111	  size?: number;
112	  strokeWidth?: number;
113	}
114	
115	const CircularScore = ({ score, size = 44, strokeWidth = 4 }: CircularScoreProps) => {
116	  if (score === null) {
117	    return (
118	      <span className="text-sm font-medium text-muted-foreground w-[44px] flex items-center justify-center">
119	        —
120	      </span>
121	    );
122	  }
123	
124	  const radius = (size - strokeWidth) / 2;
125	  const circumference = 2 * Math.PI * radius;
126	  const progress = Math.min(Math.max(score, 0), 100);
127	  const dashOffset = circumference - (progress / 100) * circumference;
128	  const color = scoreColor(progress);
129	
130	  return (
131	    <div className="relative flex items-center justify-center" style={{ width: size, height: size }}>
132	      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="-rotate-90">
133	        <circle
134	          cx={size / 2}
135	          cy={size / 2}
136	          r={radius}
137	          fill="none"
138	          stroke="currentColor"
139	          strokeWidth={strokeWidth}
140	          className="text-muted/30"
141	        />
142	        <circle
143	          cx={size / 2}
144	          cy={size / 2}
145	          r={radius}
146	          fill="none"
147	          stroke={color}
148	          strokeWidth={strokeWidth}
149	          strokeDasharray={circumference}
150	          strokeDashoffset={dashOffset}
151	          strokeLinecap="round"
152	        />
153	      </svg>
154	      <span
155	        className="absolute text-[10px] font-bold tabular-nums"
156	        style={{ color }}
157	      >
158	        {Math.round(progress)}%
159	      </span>
160	    </div>
161	  );
162	};
163	
164	// ─── Skeleton Row ─────────────────────────────────────────────────────────────
165	
166	const SkeletonRow = () => (
167	  <tr className="border-b border-border last:border-0">
168	    {[1, 2, 3, 4, 5, 6].map((i) => (
169	      <td key={i} className="px-4 py-3.5">
170	        <Skeleton className="h-4 w-full rounded" />
171	      </td>
172	    ))}
173	  </tr>
174	);
175	
176	// ─── Main Component ───────────────────────────────────────────────────────────
177	
178	const JobsOverviewCard = ({ jobs, loading, onSelectJob }: JobsOverviewCardProps) => {
179	  const [search, setSearch] = useState("");
180	  const [statusFilter, setStatusFilter] = useState<string>("all");
181	  const [sortOption, setSortOption] = useState<SortOption>("latest");
182	  const [page, setPage] = useState(1);
183	  const [avgScores, setAvgScores] = useState<Record<string, number>>({});
184	
185	  // Fetch average scores for all jobs
186	  useEffect(() => {
187	    if (jobs.length === 0) return;
188	    const jobIds = jobs.map((j) => j.id);
189	
190	    supabase
191	      .from("results")
192	      .select("job_id, overall_score")
193	      .in("job_id", jobIds)
194	      .then(({ data }) => {
195	        if (!data) return;
196	        const grouped: Record<string, number[]> = {};
197	        for (const row of data) {
198	          if (row.job_id && row.overall_score != null) {
199	            if (!grouped[row.job_id]) grouped[row.job_id] = [];
200	            grouped[row.job_id].push(row.overall_score);
201	          }
202	        }
203	        const averages: Record<string, number> = {};
204	        for (const [jobId, scores] of Object.entries(grouped)) {
205	          averages[jobId] = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
206	        }
207	        setAvgScores(averages);
208	      });
209	  }, [jobs]);
210	
211	  // Reset page when filters change
212	  useEffect(() => {
213	    setPage(1);
214	  }, [search, statusFilter, sortOption]);
215	
216	  const filtered = useMemo(() => {
217	    let list = [...jobs];
218	
219	    if (search.trim()) {
220	      const q = search.toLowerCase();
221	      list = list.filter((j) => (j.title ?? "").toLowerCase().includes(q));
222	    }
223	
224	    if (statusFilter !== "all") {
225	      list = list.filter((j) => j.status === statusFilter);
226	    }
227	
228	    list.sort((a, b) => {
229	      switch (sortOption) {
230	        case "latest":
231	          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
232	        case "oldest":
233	          return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
234	        case "name_asc":
235	          return (a.title ?? "").localeCompare(b.title ?? "");
236	        case "name_desc":
237	          return (b.title ?? "").localeCompare(a.title ?? "");
238	        case "resumes_desc":
239	          return b.resume_count - a.resume_count;
240	        case "score_desc": {
241	          const sa = avgScores[a.id] ?? -1;
242	          const sb = avgScores[b.id] ?? -1;
243	          return sb - sa;
244	        }
245	        default:
246	          return 0;
247	      }
248	    });
249	
250	    return list;
251	  }, [jobs, search, statusFilter, sortOption, avgScores]);
252	
253	  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
254	  const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
255	  const startIndex = filtered.length === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;
256	  const endIndex = Math.min(page * PAGE_SIZE, filtered.length);
257	
258	  return (
259	    <Card className="w-full shadow-sm border border-border rounded-xl overflow-hidden">
260	      {/* ── Header ── */}
261	      <CardHeader className="px-6 pt-5 pb-4 border-b border-border">
262	        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
263	          <div>
264	            <CardTitle className="text-base font-semibold text-foreground">Jobs Overview</CardTitle>
265	            <p className="text-sm text-muted-foreground mt-0.5">
266	              Track and manage all your job postings.
267	            </p>
268	          </div>
269	          <span className="text-xs text-muted-foreground font-medium tabular-nums hidden sm:block">
270	            {filtered.length} job{filtered.length !== 1 ? "s" : ""}
271	          </span>
272	        </div>
273	      </CardHeader>
274	
275	      <CardContent className="p-0">
276	        {/* ── Filter Bar ── */}
277	        <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border bg-muted/20">
278	          {/* Search */}
279	          <div className="relative flex-1 min-w-[160px] max-w-[280px]">
280	            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
281	            <Input
282	              placeholder="Search jobs..."
283	              value={search}
284	              onChange={(e) => setSearch(e.target.value)}
285	              className="h-8 pl-8 text-sm bg-background"
286	            />
287	          </div>
288	
289	          {/* Status filter */}
290	          <Select value={statusFilter} onValueChange={setStatusFilter}>
291	            <SelectTrigger className="h-8 w-[130px] text-sm bg-background">
292	              <SelectValue placeholder="Status" />
293	            </SelectTrigger>
294	            <SelectContent>
295	              <SelectItem value="all">All Status</SelectItem>
296	              <SelectItem value="pending">Pending</SelectItem>
297	              <SelectItem value="processing">Processing</SelectItem>
298	              <SelectItem value="completed">Completed</SelectItem>
299	              <SelectItem value="failed">Failed</SelectItem>
300	            </SelectContent>
301	          </Select>
302	
303	          {/* Sort */}
304	          <Select value={sortOption} onValueChange={(v) => setSortOption(v as SortOption)}>
305	            <SelectTrigger className="h-8 w-[150px] text-sm bg-background">
306	              <ArrowUpDown className="h-3.5 w-3.5 mr-1.5 text-muted-foreground" />
307	              <SelectValue placeholder="Sort" />
308	            </SelectTrigger>
309	            <SelectContent>
310	              <SelectItem value="latest">Latest First</SelectItem>
311	              <SelectItem value="oldest">Oldest First</SelectItem>
312	              <SelectItem value="name_asc">Name A–Z</SelectItem>
313	              <SelectItem value="name_desc">Name Z–A</SelectItem>
314	              <SelectItem value="resumes_desc">Most Resumes</SelectItem>
315	              <SelectItem value="score_desc">Highest Score</SelectItem>
316	            </SelectContent>
317	          </Select>
318	        </div>
319	
320	        {/* ── Table ── */}
321	        <div className="overflow-x-auto">
322	          <table className="w-full text-sm">
323	            <thead>
324	              <tr className="border-b border-border bg-muted/10">
325	                <th className="text-left text-xs font-medium text-muted-foreground px-6 py-2.5 whitespace-nowrap">
326	                  Job Title
327	                </th>
328	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
329	                  Resumes
330	                </th>
331	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
332	                  Avg. Match Score
333	                </th>
334	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
335	                  Status
336	                </th>
337	                <th className="text-left text-xs font-medium text-muted-foreground px-4 py-2.5 whitespace-nowrap">
338	                  Created On
339	                </th>
340	                <th className="px-4 py-2.5" />
341	              </tr>
342	            </thead>
343	            <tbody>
344	              {loading ? (
345	                Array.from({ length: 5 }).map((_, i) => <SkeletonRow key={i} />)
346	              ) : paginated.length === 0 ? (
347	                <tr>
348	                  <td colSpan={6} className="px-6 py-12 text-center text-sm text-muted-foreground">
349	                    {search || statusFilter !== "all"
350	                      ? "No jobs match your filters."
351	                      : "No jobs yet. Create your first job to get started."}
352	                  </td>
353	                </tr>
354	              ) : (
355	                paginated.map((job, idx) => {
356	                  const globalIdx = (page - 1) * PAGE_SIZE + idx;
357	                  const { Icon, colorClass } = getJobIconProps(job.title, globalIdx);
358	                  const tags = extractEmploymentTags(job.jd_analysis_json);
359	                  const avgScore = job.resume_count > 0 ? (avgScores[job.id] ?? null) : null;
360	
361	                  return (
362	                    <tr
363	                      key={job.id}
364	                      className="border-b border-border last:border-0 hover:bg-muted/30 cursor-pointer transition-colors group"
365	                      onClick={() => onSelectJob(job.id)}
366	                    >
367	                      {/* Job Title */}
368	                      <td className="px-6 py-3.5">
369	                        <div className="flex items-center gap-3 min-w-0">
370	                          <div
371	                            className={cn(
372	                              "h-9 w-9 rounded-lg flex items-center justify-center shrink-0",
373	                              colorClass
374	                            )}
375	                          >
376	                            <Icon className="h-4 w-4" />
377	                          </div>
378	                          <div className="min-w-0">
379	                            <p className="font-medium text-foreground truncate max-w-[220px]">
380	                              {job.title || "Untitled Job"}
381	                            </p>
382	                            {tags.length > 0 && (
383	                              <p className="text-xs text-muted-foreground mt-0.5 truncate">
384	                                {tags.join(" · ")}
385	                              </p>
386	                            )}
387	                          </div>
388	                        </div>
389	                      </td>
390	
391	                      {/* Resumes */}
392	                      <td className="px-4 py-3.5">
393	                        <span className="font-medium tabular-nums text-foreground">
394	                          {job.resume_count}
395	                        </span>
396	                      </td>
397	
398	                      {/* Avg Match Score */}
399	                      <td className="px-4 py-3.5">
400	                        <CircularScore score={avgScore} />
401	                      </td>
402	
403	                      {/* Status */}
404	                      <td className="px-4 py-3.5">
405	                        <StatusBadge status={job.status} />
406	                      </td>
407	
408	                      {/* Created On */}
409	                      <td className="px-4 py-3.5 whitespace-nowrap text-muted-foreground text-xs">
410	                        {format(new Date(job.created_at), "MMM d, yyyy")}
411	                      </td>
412	
413	                      {/* Arrow */}
414	                      <td className="px-4 py-3.5">
415	                        <ChevronRight className="h-4 w-4 text-muted-foreground group-hover:text-foreground transition-colors" />
416	                      </td>
417	                    </tr>
418	                  );
419	                })
420	              )}
421	            </tbody>
422	          </table>
423	        </div>
424	
425	        {/* ── Pagination ── */}
426	        {!loading && filtered.length > 0 && (
427	          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-6 py-3 border-t border-border bg-muted/10">
428	            <p className="text-xs text-muted-foreground">
429	              Showing {startIndex}–{endIndex} of {filtered.length} job{filtered.length !== 1 ? "s" : ""}
430	            </p>
431	
432	            {totalPages > 1 && (
433	              <div className="flex items-center gap-1">
434	                <Button
435	                  variant="outline"
436	                  size="sm"
437	                  className="h-7 px-2.5 text-xs"
438	                  onClick={() => setPage((p) => Math.max(1, p - 1))}
439	                  disabled={page === 1}
440	                >
441	                  Prev
442	                </Button>
443	
444	                {Array.from({ length: totalPages }).map((_, i) => {
445	                  const pageNum = i + 1;
446	                  // Show first, last, and pages near current
447	                  const nearCurrent = Math.abs(pageNum - page) <= 1;
448	                  const isFirst = pageNum === 1;
449	                  const isLast = pageNum === totalPages;
450	                  if (!nearCurrent && !isFirst && !isLast) {
451	                    // Show ellipsis placeholder once per gap
452	                    if (pageNum === 2 && page > 3) return <span key={pageNum} className="text-xs text-muted-foreground px-1">…</span>;
453	                    if (pageNum === totalPages - 1 && page < totalPages - 2) return <span key={pageNum} className="text-xs text-muted-foreground px-1">…</span>;
454	                    return null;
455	                  }
456	                  return (
457	                    <Button
458	                      key={pageNum}
459	                      variant={page === pageNum ? "default" : "outline"}
460	                      size="sm"
461	                      className="h-7 w-7 p-0 text-xs"
462	                      onClick={() => setPage(pageNum)}
463	                    >
464	                      {pageNum}
465	                    </Button>
466	                  );
467	                })}
468	
469	                <Button
470	                  variant="outline"
471	                  size="sm"
472	                  className="h-7 px-2.5 text-xs"
473	                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
474	                  disabled={page === totalPages}
475	                >
476	                  Next
477	                </Button>
478	              </div>
479	            )}
480	          </div>
481	        )}
482	      </CardContent>
483	    </Card>
484	  );
485	};
486	
487	// ─── Status Badge ─────────────────────────────────────────────────────────────
488	
489	function StatusBadge({ status }: { status: string }) {
490	  switch (status) {
491	    case "completed":
492	      return <Badge variant="success" className="capitalize text-xs font-medium">Completed</Badge>;
493	    case "processing":
494	      return <Badge variant="warning" className="capitalize text-xs font-medium">Processing</Badge>;
495	    case "pending":
496	      return <Badge variant="warning" className="capitalize text-xs font-medium">Pending</Badge>;
497	    case "failed":
498	      return <Badge variant="destructive" className="capitalize text-xs font-medium">Failed</Badge>;
499	    default:
500	      return <Badge variant="outline" className="capitalize text-xs font-medium">{status}</Badge>;
501	  }
502	}
503	
504	export default JobsOverviewCard;
