import { useState, useCallback, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import AppHeader from "@/components/AppHeader";
import JobsOverviewCard from "@/components/JobsOverviewCard";
import { Button } from "@/components/ui/button";
import { Plus } from "lucide-react";
import { toast } from "sonner";
import type { PastJob } from "@/pages/Index";

const MyJobs = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [jobs, setJobs] = useState<PastJob[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchJobs = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    supabase
      .from("jobs")
      .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false })
      .limit(100)
      .then(({ data, error }) => {
        if (error) {
          toast.error("Failed to load jobs");
          return;
        }
        if (data) {
          setJobs(data.map((j: any) => ({
            id: j.id,
            title: j.title,
            job_description: j.job_description,
            status: j.status,
            created_at: j.created_at,
            resume_count: j.resumes?.[0]?.count ?? 0,
            jd_analysis_json: j.jd_analysis_json,
            dynamic_weights_json: j.dynamic_weights_json,
            inbox_email: j.inbox_email ?? null,
          })));
        }
      })
      .finally(() => setLoading(false));
  }, [user]);

  useEffect(() => {
    fetchJobs();
  }, [fetchJobs]);

  const handleSelectJob = (jobId: string) => {
    navigate(`/?job=${jobId}`);
  };

  const handleCreateJob = () => {
    navigate("/?new=1");
  };

  return (
    <div className="min-h-svh bg-background">
      <AppHeader />
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
        {/* Page header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
            <p className="text-sm text-muted-foreground mt-1">Manage all your job postings.</p>
          </div>
          <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleCreateJob}>
            <Plus className="h-4 w-4" /> Create Job
          </Button>
        </div>

        {/* Full jobs table */}
        <JobsOverviewCard jobs={jobs} loading={loading} onSelectJob={handleSelectJob} />
      </div>
    </div>
  );
};

export default MyJobs;

